import { Request, Response } from 'express';
import { CreateProjectUseCase } from '../application/CreateProjectUseCase';

export class ProjectController {
  constructor(private createProjectUseCase: CreateProjectUseCase) {}

  create(req: Request, res: Response): void {
    const { id, name } = req.body;
    if (!id || !name) {
      res.status(400).json({ error: 'Missing required fields: id, name' });
      return;
    }

    const project = this.createProjectUseCase.execute(id, name);
    res.status(201).json(project);
  }
}

